script:
frappe.db.get_single_value("Jewellery Settings", "default_gst_rate").then(function(value) {
    window.__jewellery_default_gst_rate = value || 3;
});

function prefill_gst_rate(frm) {
    if (!frm.doc.gst_rate || frm.doc.gst_rate === 3) {
        frm.set_value("gst_rate", window.__jewellery_default_gst_rate || 3);
    }
}

frappe.ui.form.on("Jewellery Purchase Invoice", {

    refresh: function(frm) {
        if (frm.is_new()) {
            prefill_gst_rate(frm);
        } else {
            calculate_purchase(frm);
        }
    },

    items_add: function(frm) {
        calculate_purchase(frm);
    },

    items_remove: function(frm) {
        calculate_purchase(frm);
    },

    payments_add: function(frm) {
        calculate_purchase(frm);
    },

    payments_remove: function(frm) {
        calculate_purchase(frm);
    },

    gst_rate: function(frm) {
        calculate_purchase(frm);
    }
});


/* ======================================================
   JEWELLERY PURCHASE ITEM
   ====================================================== */

frappe.ui.form.on("Jewellery Purchase Item", {

    retail_stock_item: function(frm, cdt, cdn) {
        fetch_retail_stock_item_details(frm, cdt, cdn);
    },

    purity: function(frm, cdt, cdn) {
        fetch_purchase_purity_percentage(frm, cdt, cdn);
    },

    gross_weight: function(frm, cdt, cdn) {
        calculate_purchase_item(frm, cdt, cdn);
    },

    net_weight: function(frm, cdt, cdn) {
        calculate_purchase_item(frm, cdt, cdn);
    },

    purity_percentage: function(frm, cdt, cdn) {
        calculate_purchase_item(frm, cdt, cdn);
    },

    wastage_percentage: function(frm, cdt, cdn) {
        calculate_purchase_item(frm, cdt, cdn);
    },

    rate_24k: function(frm, cdt, cdn) {
        calculate_purchase_item(frm, cdt, cdn);
    },

    making_charges: function(frm, cdt, cdn) {
        calculate_purchase_item(frm, cdt, cdn);
    },

    stone_charges: function(frm, cdt, cdn) {
        calculate_purchase_item(frm, cdt, cdn);
    },

    other_charges: function(frm, cdt, cdn) {
        calculate_purchase_item(frm, cdt, cdn);
    }
});


/* ======================================================
   PURCHASE PAYMENT
   ====================================================== */

frappe.ui.form.on("Jewellery Purchase Payment", {

    amount: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        let paid_by_other_payments = 0;

        (frm.doc.payments || []).forEach(function(payment) {

            if (payment.name !== row.name) {
                paid_by_other_payments += flt(payment.amount);
            }
        });

        let grand_total = flt(frm.doc.grand_total);

        let remaining_balance =
            grand_total - paid_by_other_payments;

        if (remaining_balance < 0) {
            remaining_balance = 0;
        }

        if (flt(row.amount) > remaining_balance) {

            frappe.msgprint({
                title: "Payment Exceeds Balance",
                message:
                    "Payment cannot be greater than the remaining balance of " +
                    format_currency(remaining_balance),
                indicator: "red"
            });

            frappe.model.set_value(
                cdt,
                cdn,
                "amount",
                0
            );
        }

        calculate_purchase(frm);
    },

    payment_date: function(frm) {
        calculate_purchase(frm);
    },

    payment_mode: function(frm) {
        calculate_purchase(frm);
    }
});


/* ======================================================
   FETCH RETAIL STOCK ITEM
   ====================================================== */

function fetch_retail_stock_item_details(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    if (!row.retail_stock_item) {
        return;
    }

    frappe.db.get_doc(
        "Retail Stock Item",
        row.retail_stock_item
    ).then(function(stock) {

        let values = {};

        /*
         * Retail Stock Item is the exact physical
         * stock identity.
         */

        if (stock.article_category) {
            values.item_name = stock.article_category;
        }

        /*
         * UNIVERSAL PURITY
         *
         * Same field for Gold and Silver.
         */
        if (stock.purity) {
            values.purity = stock.purity;
        }

        /*
         * Set fetched values.
         * These remain editable in the Purchase Item,
         * because the purchase transaction records
         * what was actually bought.
         */

        Object.keys(values).forEach(function(fieldname) {

            frappe.model.set_value(
                cdt,
                cdn,
                fieldname,
                values[fieldname]
            );

        });

        /*
         * Fetch the percentage from the universal
         * Metal Purity master.
         */

        if (stock.purity) {

            frappe.db.get_value(
                "Metal Purity",
                stock.purity,
                "purity_"
            ).then(function(r) {

                if (
                    r.message &&
                    r.message.purity_ !== undefined
                ) {

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "purity_percentage",
                        flt(r.message.purity_)
                    );

                    calculate_purchase_item(
                        frm,
                        cdt,
                        cdn
                    );
                }

            });

        } else {

            calculate_purchase_item(
                frm,
                cdt,
                cdn
            );
        }

    });
}


/* ======================================================
   FETCH PURCHASE PURITY PERCENTAGE
   ====================================================== */

function fetch_purchase_purity_percentage(
    frm,
    cdt,
    cdn
) {

    let row = locals[cdt][cdn];

    if (!row.purity) {
        return;
    }

    frappe.db.get_value(
        "Metal Purity",
        row.purity,
        "purity_"
    ).then(function(r) {

        if (
            r.message &&
            r.message.purity_ !== undefined
        ) {

            frappe.model.set_value(
                cdt,
                cdn,
                "purity_percentage",
                flt(r.message.purity_)
            );

            calculate_purchase_item(
                frm,
                cdt,
                cdn
            );
        }

    });
}


/* ======================================================
   CALCULATE ONE PURCHASE ITEM
   ====================================================== */

function calculate_purchase_item(
    frm,
    cdt,
    cdn
) {

    let row = locals[cdt][cdn];

    /*
     * Net Weight if entered.
     * Otherwise Gross Weight.
     */

    let weight =
        flt(row.net_weight);

    if (weight <= 0) {
        weight =
            flt(row.gross_weight);
    }


    let purity_percentage =
        flt(row.purity_percentage);

    let wastage_percentage =
        flt(row.wastage_percentage);


    /*
     * Purchase Pure Equivalent Weight
     *
     * Weight ×
     * (Purity + Wastage) / 100
     */

    let pure_weight_24k =
        weight *
        (purity_percentage + wastage_percentage) /
        100;


    /*
     * Maximum 3 decimal places.
     */

    pure_weight_24k =
        Math.round(
            (pure_weight_24k + Number.EPSILON) *
            1000
        ) / 1000;


    let pure_rate =
        flt(row.rate_24k);


    /*
     * Gold / Silver Value
     */

    let metal_value =
        pure_weight_24k *
        pure_rate;


    /*
     * Money is whole rupees and rounds UP.
     */

    metal_value =
        Math.ceil(metal_value);


    let making_charges =
        flt(row.making_charges);

    let stone_charges =
        flt(row.stone_charges);

    let other_charges =
        flt(row.other_charges);


    let total_amount =
        metal_value +
        making_charges +
        stone_charges +
        other_charges;


    total_amount =
        Math.ceil(total_amount);


    frappe.model.set_value(
        cdt,
        cdn,
        "pure_weight_24k",
        pure_weight_24k
    );

    frappe.model.set_value(
        cdt,
        cdn,
        "metal_value",
        metal_value
    );

    frappe.model.set_value(
        cdt,
        cdn,
        "total_amount",
        total_amount
    );

    calculate_purchase(frm);
}


/* ======================================================
   CALCULATE PURCHASE INVOICE
   ====================================================== */

function calculate_purchase(frm) {

    let gross_total_weight = 0;
    let net_total_weight = 0;
    let total_pure_weight_24k = 0;
    let total_metal_value = 0;
    let total_making_charges = 0;
    let total_stone_charges = 0;
    let total_other_charges = 0;


    (frm.doc.items || []).forEach(function(row) {

        gross_total_weight +=
            flt(row.gross_weight);


        let net_weight =
            flt(row.net_weight);

        if (net_weight <= 0) {
            net_weight =
                flt(row.gross_weight);
        }

        net_total_weight +=
            net_weight;


        total_pure_weight_24k +=
            flt(row.pure_weight_24k);

        total_metal_value +=
            flt(row.metal_value);

        total_making_charges +=
            flt(row.making_charges);

        total_stone_charges +=
            flt(row.stone_charges);

        total_other_charges +=
            flt(row.other_charges);

    });


    /*
     * Weight totals → maximum 3 decimals.
     */

    gross_total_weight =
        Math.round(
            (gross_total_weight + Number.EPSILON) *
            1000
        ) / 1000;


    net_total_weight =
        Math.round(
            (net_total_weight + Number.EPSILON) *
            1000
        ) / 1000;


    total_pure_weight_24k =
        Math.round(
            (total_pure_weight_24k + Number.EPSILON) *
            1000
        ) / 1000;


    /*
     * Whole-rupee money.
     */

    total_metal_value =
        Math.ceil(total_metal_value);

    total_making_charges =
        Math.ceil(total_making_charges);

    total_stone_charges =
        Math.ceil(total_stone_charges);

    total_other_charges =
        Math.ceil(total_other_charges);


    let subtotal =
        total_metal_value +
        total_making_charges +
        total_stone_charges +
        total_other_charges;


    subtotal =
        Math.ceil(subtotal);


    /*
     * GST (configurable per invoice; 0 allowed).
     */

    const gst_rate =
        flt(frm.doc.gst_rate);

    const gst =
        flt(subtotal * gst_rate / 100, 2);

    let grand_total =
        Math.ceil(subtotal + gst);


    let total_paid = 0;


    (frm.doc.payments || []).forEach(function(payment) {

        total_paid +=
            flt(payment.amount);

    });


    total_paid =
        Math.ceil(total_paid);


    let balance_amount =
        grand_total -
        total_paid;


    if (balance_amount < 0) {
        balance_amount = 0;
    }


    balance_amount =
        Math.ceil(balance_amount);


    /*
     * Update parent.
     */

    frm.set_value(
        "gross_total_weight",
        gross_total_weight
    );

    frm.set_value(
        "net_total_weight",
        net_total_weight
    );

    frm.set_value(
        "total_pure_weight_24k",
        total_pure_weight_24k
    );

    frm.set_value(
        "total_metal_value",
        total_metal_value
    );

    frm.set_value(
        "total_making_charges",
        total_making_charges
    );

    frm.set_value(
        "total_stone_charges",
        total_stone_charges
    );

    frm.set_value(
        "total_other_charges",
        total_other_charges
    );

    frm.set_value(
        "subtotal",
        subtotal
    );


    frm.set_value(
        "gst",
        gst
    );

    frm.set_value(
        "grand_total",
        grand_total
    );

    frm.set_value(
        "total_paid",
        total_paid
    );

    frm.set_value(
        "balance_amount",
        balance_amount
    );
}

frappe.db.get_single_value("Jewellery Settings", "default_gst_rate").then(function(value) {
    window.__jewellery_default_gst_rate = value || 3;
});

function prefill_gst_rate(frm) {
    if (!frm.doc.gst_rate || frm.doc.gst_rate === 3) {
        frm.set_value("gst_rate", window.__jewellery_default_gst_rate || 3);
    }
}

frappe.ui.form.on("Jewellery Sales Invoice", {

    refresh: function(frm) {
        if (frm.is_new()) {
            prefill_gst_rate(frm);
        } else {
            calculate_sales(frm);
        }
    },

    items_add: function(frm) {
        calculate_sales(frm);
    },

    items_remove: function(frm) {
        calculate_sales(frm);
    },

    payments_add: function(frm) {
        calculate_sales(frm);
    },

    payments_remove: function(frm) {
        calculate_sales(frm);
    },

    gst_rate: function(frm) {
        calculate_sales(frm);
    },

    tcs_rate: function(frm) {
        calculate_sales(frm);
    },

    old_gold_credit: function(frm) {
        calculate_sales(frm);
    },

    old_gold_receipt: function(frm) {
        autofill_old_gold_credit(frm);
    }
});


function autofill_old_gold_credit(frm) {

    if (
        !frm.doc.old_gold_receipt ||
        flt(frm.doc.old_gold_credit) > 0
    ) {
        calculate_sales(frm);
        return;
    }

    frappe.db.get_value(
        "Old Gold Receipt",
        frm.doc.old_gold_receipt,
        "credit_amount"
    ).then(function(r) {

        const credit =
            r && r.message
                ? flt(r.message.credit_amount)
                : 0;

        if (credit > 0) {
            frm.set_value(
                "old_gold_credit",
                credit
            );
        }

        calculate_sales(frm);

    });
}


/* ======================================================
   JEWELLERY SALES ITEM
   ====================================================== */

frappe.ui.form.on("Jewellery Sales Item", {

    retail_stock_item: function(frm, cdt, cdn) {
        fetch_sales_retail_stock_item_details(
            frm,
            cdt,
            cdn
        );
    },

    purity: function(frm, cdt, cdn) {
        fetch_sales_purity_percentage(
            frm,
            cdt,
            cdn
        );
    },

    gross_weight: function(frm, cdt, cdn) {
        calculate_sales_item(frm, cdt, cdn);
    },

    net_weight: function(frm, cdt, cdn) {
        calculate_sales_item(frm, cdt, cdn);
    },

    purity_percentage: function(frm, cdt, cdn) {
        calculate_sales_item(frm, cdt, cdn);
    },

    wastage_percentage: function(frm, cdt, cdn) {
        calculate_sales_item(frm, cdt, cdn);
    },

    rate_24k: function(frm, cdt, cdn) {
        calculate_sales_item(frm, cdt, cdn);
    },

    making_charges: function(frm, cdt, cdn) {
        calculate_sales_item(frm, cdt, cdn);
    }
});


/* ======================================================
   JEWELLERY SALES PAYMENT
   ====================================================== */

frappe.ui.form.on("Jewellery Sales Payment", {

    amount: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        let paid_by_other_payments = 0;


        (frm.doc.payments || []).forEach(function(payment) {

            if (payment.name !== row.name) {

                paid_by_other_payments +=
                    flt(payment.amount);

            }

        });


        let grand_total =
            flt(frm.doc.grand_total);


        let remaining_balance =
            grand_total -
            paid_by_other_payments;


        if (remaining_balance < 0) {
            remaining_balance = 0;
        }


        if (flt(row.amount) > remaining_balance) {

            frappe.msgprint({
                title: "Payment Exceeds Balance",
                message:
                    "Payment cannot be greater than the remaining balance of " +
                    format_currency(remaining_balance),
                indicator: "red"
            });


            frappe.model.set_value(
                cdt,
                cdn,
                "amount",
                0
            );
        }


        calculate_sales(frm);
    },


    payment_date: function(frm) {
        calculate_sales(frm);
    },


    payment_mode: function(frm) {
        calculate_sales(frm);
    }
});


/* ======================================================
   FETCH RETAIL STOCK ITEM DETAILS
   ====================================================== */

function fetch_sales_retail_stock_item_details(
    frm,
    cdt,
    cdn
) {

    let row = locals[cdt][cdn];

    if (!row.retail_stock_item) {
        return;
    }


    frappe.db.get_doc(
        "Retail Stock Item",
        row.retail_stock_item
    ).then(function(stock) {

        let values = {};


        /*
         * Universal Item Category
         */

        if (stock.article_category) {

            values.item_name =
                stock.article_category;

        }


        /*
         * UNIVERSAL PURITY
         *
         * Gold and Silver both use:
         *
         * Retail Stock Item.purity
         */

        if (stock.purity) {

            values.purity =
                stock.purity;

        }


        Object.keys(values).forEach(function(fieldname) {

            frappe.model.set_value(
                cdt,
                cdn,
                fieldname,
                values[fieldname]
            );

        });


        /*
         * Fetch universal purity percentage.
         */

        if (stock.purity) {

            frappe.db.get_value(
                "Metal Purity",
                stock.purity,
                "purity_"
            ).then(function(r) {

                if (
                    r.message &&
                    r.message.purity_ !== undefined
                ) {

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "purity_percentage",
                        flt(r.message.purity_)
                    );

                    calculate_sales_item(
                        frm,
                        cdt,
                        cdn
                    );

                }

            });

        } else {

            calculate_sales_item(
                frm,
                cdt,
                cdn
            );

        }

    });
}


/* ======================================================
   FETCH SALES PURITY PERCENTAGE
   ====================================================== */

function fetch_sales_purity_percentage(
    frm,
    cdt,
    cdn
) {

    let row = locals[cdt][cdn];

    if (!row.purity) {
        return;
    }


    frappe.db.get_value(
        "Metal Purity",
        row.purity,
        "purity_"
    ).then(function(r) {

        if (
            r.message &&
            r.message.purity_ !== undefined
        ) {

            frappe.model.set_value(
                cdt,
                cdn,
                "purity_percentage",
                flt(r.message.purity_)
            );


            calculate_sales_item(
                frm,
                cdt,
                cdn
            );

        }

    });
}


/* ======================================================
   CALCULATE SALES ITEM
   ====================================================== */

function calculate_sales_item(
    frm,
    cdt,
    cdn
) {

    let row = locals[cdt][cdn];


    /*
     * Base physical weight.
     *
     * Net Weight when entered,
     * otherwise Gross Weight.
     */

    let weight =
        flt(row.net_weight);


    if (weight <= 0) {

        weight =
            flt(row.gross_weight);

    }


    /*
     * Wastage is OPTIONAL.
     *
     * 0% means no wastage.
     */

    let wastage_percentage =
        flt(row.wastage_percentage);


    let chargeable_weight =
        weight *
        (
            1 +
            wastage_percentage / 100
        );


    /*
     * Weight maximum 3 decimals.
     */

    chargeable_weight =
        Math.round(
            (chargeable_weight + Number.EPSILON) *
            1000
        ) / 1000;


    /*
     * Pure Rate Per Gram
     */

    let pure_rate =
        flt(row.rate_24k);


    /*
     * Gold / Silver Value
     */

    let metal_value =
        chargeable_weight *
        pure_rate;


    /*
     * Whole rupees.
     * Always round UP.
     */

    metal_value =
        Math.ceil(metal_value);


    /*
     * Making Charges
     */

    let making_charges =
        flt(row.making_charges);


    /*
     * Final Item Total
     */

    let total_amount =
        metal_value +
        making_charges;


    total_amount =
        Math.ceil(total_amount);


    frappe.model.set_value(
        cdt,
        cdn,
        "chargeable_weight",
        chargeable_weight
    );


    frappe.model.set_value(
        cdt,
        cdn,
        "metal_value",
        metal_value
    );


    frappe.model.set_value(
        cdt,
        cdn,
        "total_amount",
        total_amount
    );


    calculate_sales(frm);
}


/* ======================================================
   CALCULATE SALES INVOICE
   ====================================================== */

function calculate_sales(frm) {

    let gross_total_weight = 0;

    let net_total_weight = 0;

    let total_chargeable_weight = 0;

    let total_metal_value = 0;

    let total_making_charges = 0;


    (frm.doc.items || []).forEach(function(row) {


        gross_total_weight +=
            flt(row.gross_weight);


        let net_weight =
            flt(row.net_weight);


        if (net_weight <= 0) {

            net_weight =
                flt(row.gross_weight);

        }


        net_total_weight +=
            net_weight;


        total_chargeable_weight +=
            flt(row.chargeable_weight);


        total_metal_value +=
            flt(row.metal_value);


        total_making_charges +=
            flt(row.making_charges);

    });


    /*
     * Maximum 3 decimals for weights.
     */

    gross_total_weight =
        Math.round(
            (gross_total_weight + Number.EPSILON) *
            1000
        ) / 1000;


    net_total_weight =
        Math.round(
            (net_total_weight + Number.EPSILON) *
            1000
        ) / 1000;


    total_chargeable_weight =
        Math.round(
            (total_chargeable_weight + Number.EPSILON) *
            1000
        ) / 1000;


    /*
     * Whole rupee money.
     */

    total_metal_value =
        Math.ceil(total_metal_value);


    total_making_charges =
        Math.ceil(total_making_charges);


    /*
     * Subtotal.
     */

    let subtotal =
        total_metal_value +
        total_making_charges;


    subtotal =
        Math.ceil(subtotal);


    /*
     * GST (configurable per invoice; 0 allowed).
     */

    const gst_rate =
        flt(frm.doc.gst_rate);

    const gst_amount =
        flt(subtotal * gst_rate / 100, 2);

    /*
     * Old-gold exchange credit (linked receipt, never a
     * negative item). Clamped so the bill cannot go below zero.
     */

    let old_gold_credit =
        flt(frm.doc.old_gold_credit);

    const max_credit =
        subtotal + gst_amount;

    if (max_credit <= 0) {
        /*
         * Return (negative-bill) invoices can never carry an
         * old-gold credit; without this guard the clamp below
         * would set the credit to the negative max and zero
         * out grand_total.
         */
        old_gold_credit = 0;

        if (flt(frm.doc.old_gold_credit) != 0) {
            frappe.model.set_value(
                frm.doctype,
                frm.docname,
                "old_gold_credit",
                0
            );
        }
    } else if (old_gold_credit > max_credit) {
        old_gold_credit = max_credit;

        frappe.model.set_value(
            frm.doctype,
            frm.docname,
            "old_gold_credit",
            flt(max_credit, 2)
        );
    }

    let grand_total =
        Math.ceil(subtotal + gst_amount - old_gold_credit);


    /*
     * TCS on sales above the settings threshold (0.1% default,
     * whole-rupee CEIL; mirrors the server _compute_tcs_amount).
     * Return (negative-bill) invoices never carry TCS.
     */

    let tcs_amount = 0;

    const tcs_threshold =
        flt(frappe.boot.jewellery_settings_tcs_threshold);

    const tcs_rate_setting =
        flt(frappe.boot.jewellery_settings_tcs_rate);

    if (grand_total > 0 && grand_total >= tcs_threshold) {

        const tcs_rate =
            flt(frm.doc.tcs_rate) > 0
                ? flt(frm.doc.tcs_rate)
                : tcs_rate_setting;

        tcs_amount =
            Math.ceil(grand_total * tcs_rate / 100);
    }


    /*
     * Payments.
     */

    let total_paid = 0;


    (frm.doc.payments || []).forEach(function(payment) {

        total_paid +=
            flt(payment.amount);

    });


    total_paid =
        Math.ceil(total_paid);


    /*
     * Balance.
     */

    let balance_amount =
        grand_total -
        total_paid;


    if (balance_amount < 0) {

        balance_amount = 0;

    }


    balance_amount =
        Math.ceil(balance_amount);


    /*
     * Parent values.
     */

    frm.set_value(
        "gross_total_weight",
        gross_total_weight
    );


    frm.set_value(
        "net_total_weight",
        net_total_weight
    );


    frm.set_value(
        "total_chargeable_weight",
        total_chargeable_weight
    );


    frm.set_value(
        "total_metal_value",
        total_metal_value
    );


    frm.set_value(
        "total_making_charges",
        total_making_charges
    );


    frm.set_value(
        "subtotal",
        subtotal
    );


    frm.set_value(
        "gst_amount",
        gst_amount
    );


    frm.set_value(
        "grand_total",
        grand_total
    );


    frm.set_value(
        "tcs_amount",
        tcs_amount
    );


    frm.set_value(
        "total_paid",
        total_paid
    );


    frm.set_value(
        "balance_amount",
        balance_amount
    );
}

