/* ======================================================
   FETCH RETAIL STOCK ITEM DETAILS
   ====================================================== */

function fetch_opening_stock_details(frm, cdt, cdn) {

    const row = locals[cdt][cdn];

    if (!row.retail_stock_item) {

        calculate_opening_stock(frm);
        return;
    }


    frappe.db.get_doc(
        "Retail Stock Item",
        row.retail_stock_item
    ).then(function(stock) {

        let promises = [];


        /* ----------------------------------------------
           Item Name
           ---------------------------------------------- */

        if (stock.article_category) {

            promises.push(
                frappe.model.set_value(
                    cdt,
                    cdn,
                    "item_name",
                    stock.article_category
                )
            );

        }


        /* ----------------------------------------------
           Universal Purity
           ---------------------------------------------- */

        if (stock.purity) {

            promises.push(
                frappe.model.set_value(
                    cdt,
                    cdn,
                    "purity",
                    stock.purity
                )
            );

        }


        Promise.all(promises).then(function() {

            calculate_opening_stock(frm);

        });

    });
}


/* ======================================================
   CALCULATE OPENING STOCK
   ====================================================== */

function calculate_opening_stock(frm) {

    let total_weight = 0;

    let total_value = 0;


    (frm.doc.items || []).forEach(function(row) {

        const weight = flt(row.weight);

        const rate = flt(row.rate);


        total_weight += weight;

        total_value += weight * rate;

    });


    /* ----------------------------------------------
       Weight → maximum 3 decimals
       ---------------------------------------------- */

    total_weight =
        Math.round(
            (total_weight + Number.EPSILON) * 1000
        ) / 1000;


    /* ----------------------------------------------
       Money → whole rupees
       ---------------------------------------------- */

    total_value =
        Math.ceil(total_value);


    frm.set_value(
        "total_opening_weight",
        total_weight
    );


    frm.set_value(
        "total_opening_value",
        total_value
    );


    frm.refresh_field(
        "total_opening_weight"
    );


    frm.refresh_field(
        "total_opening_value"
    );
}

