function set_stock_item_field_rules(frm) {

    const is_gold = frm.doc.metal === "Gold";
    const is_silver = frm.doc.metal === "Silver";


    /*
     * Purity is universal.
     */
    frm.set_df_property(
        "purity",
        "hidden",
        false
    );


    /*
     * Gold Size is relevant only for Gold.
     */
    frm.set_df_property(
        "gold_size",
        "hidden",
        !is_gold
    );


    /*
     * Silver Size is relevant only for Silver.
     */
    frm.set_df_property(
        "silver_size",
        "hidden",
        !is_silver
    );


    /*
     * Clear the opposite metal's size
     * when Metal changes.
     */

    if (is_gold && frm.doc.silver_size) {

        frm.set_value(
            "silver_size",
            ""
        );
    }


    if (is_silver && frm.doc.gold_size) {

        frm.set_value(
            "gold_size",
            ""
        );
    }
}

