/* ======================================================
   ITEM SUMMARY FOR KANBAN
   ====================================================== */

function update_item_summary(frm) {

    const items = frm.doc.jewellery_items || [];

    if (!items.length) {

        if (frm.doc.item_summary) {
            frm.set_value("item_summary", "");
        }

        return;
    }


    const request_id =
        (frm.__item_summary_request_id || 0) + 1;

    frm.__item_summary_request_id =
        request_id;


    const requests = items.map(function(row) {

        if (!row.item_name) {

            return Promise.resolve({
                idx: row.idx,
                text: ""
            });
        }


        return frappe.db.get_value(
            "Jewellery Item Type",
            row.item_name,
            "item_type_name"
        ).then(function(result) {

            const item_name =
                result &&
                result.message &&
                result.message.item_type_name
                    ? result.message.item_type_name
                    : row.item_name;


            const net_weight =
                flt(row.net_weight);


            let text =
                item_name;


            if (net_weight > 0) {

                text +=
                    " — " +
                    net_weight.toFixed(3) +
                    " g";
            }


            return {
                idx: row.idx,
                text: text
            };

        });

    });


    Promise.all(requests).then(function(results) {

        if (
            request_id !==
            frm.__item_summary_request_id
        ) {
            return;
        }


        results.sort(function(a, b) {
            return a.idx - b.idx;
        });


        const summary =
            results
                .filter(function(item) {
                    return item.text;
                })
                .map(function(item) {
                    return item.text;
                })
                .join("\n");


        /*
         * Set the value on the document and refresh the field.
         */

        frm.doc.item_summary =
            summary;


        frm.refresh_field(
            "item_summary"
        );


        /*
         * Make sure Frappe knows the document
         * has changed and will save the summary.
         */

        if (frm.doc.item_summary !== summary) {
            frm.set_value(
                "item_summary",
                summary
            );
        }

    });
}



/* ======================================================
   WORKER OTHER CHARGE TOTALS
   (parent-level table; applicable_items = Sr Nos "1,2,3",
   blank = whole order / visit lump, counted once at
   order total and never split across items)
   ====================================================== */

function charge_item_list(charge, valid_idxs) {

    const raw =
        (charge.applicable_items || "")
            .trim();

    if (!raw || raw === "0") {
        return [];
    }

    const out = [];

    raw.split(",").forEach(function(part) {

        const n =
            parseInt(
                String(part).trim(),
                10
            );

        if (
            !isNaN(n) &&
            valid_idxs.has(n) &&
            !out.includes(n)
        ) {
            out.push(n);
        }

    });

    return out;
}


function order_item_idxs(frm) {

    return new Set(
        (frm.doc.jewellery_items || [])
            .map(function(row) {
                return row.idx;
            })
    );
}


function update_worker_other_charge_totals(
    frm,
    cdt,
    cdn
) {

    calculate_all_worker_other_charge_totals(
        frm
    );

    update_order_worker_total(
        frm
    );
}


function calculate_all_worker_other_charge_totals(frm) {

    const valid =
        order_item_idxs(frm);

    const all_charges =
        frm.doc.worker_other_charge_details || [];

    (frm.doc.jewellery_items || [])
        .forEach(function(item) {

            const charges =
                all_charges.filter(
                    function(c) {

                        const list =
                            charge_item_list(
                                c,
                                valid
                            );

                        return (
                            list.length === 1 &&
                            list[0] === item.idx
                        );

                    }
                );

            set_worker_charge_summaries(
                frm,
                item,
                charges
            );

        });
}


function update_order_worker_total(frm) {

    const valid =
        order_item_idxs(frm);

    let total = 0;

    (frm.doc.jewellery_items || [])
        .forEach(function(item) {
            total += flt(item.worker_total_cost);
        });

    (frm.doc.worker_other_charge_details || [])
        .forEach(function(c) {

            const list =
                charge_item_list(
                    c,
                    valid
                );

            /* single-item rows already sit inside
               that item's worker_total_cost;
               shared / whole-order rows are
               counted once here */

            if (list.length !== 1) {
                total += flt(c.amount);
            }

        });

    frm.set_value(
        "total_worker_cost",
        Math.ceil(total)
    );
}


function set_worker_charge_summaries(
    frm,
    item,
    charges
) {

    let hallmark = 0;
    let document = 0;
    let travel = 0;
    let other = 0;

    charges.forEach(function(charge) {

        const amount =
            flt(charge.amount);

        if (amount <= 0) {
            return;
        }

        switch (charge.charge_type) {

            case "Hallmark":
                hallmark += amount;
                break;

            case "Certificate / Document":
                document += amount;
                break;

            case "Bus / Travel":
                travel += amount;
                break;

            default:
                other += amount;
                break;
        }
    });

    frappe.model.set_value(
        item.doctype,
        item.name,
        "worker_hallmark_charges",
        flt(hallmark, 2)
    );

    frappe.model.set_value(
        item.doctype,
        item.name,
        "worker_document_charges",
        flt(document, 2)
    );

    frappe.model.set_value(
        item.doctype,
        item.name,
        "worker_travel_charges",
        flt(travel, 2)
    );

    frappe.model.set_value(
        item.doctype,
        item.name,
        "worker_other_charges",
        flt(other, 2)
    );

    calculate_worker_side(
        frm,
        item.doctype,
        item.name
    );
}


/* ======================================================
   INITIALIZE ORDER ITEM
   ====================================================== */

function initialize_order_item(frm, cdt, cdn) {

