/* ======================================================
   NET WEIGHT DEFAULT
   ====================================================== */

function set_net_weight_if_empty(frm, cdt, cdn) {

    const row = locals[cdt][cdn];

    if (
        !flt(row.net_weight) &&
        flt(row.gross_weight)
    ) {

        frappe.model.set_value(
            cdt,
            cdn,
            "net_weight",
            flt(row.gross_weight, 3)
        );
    }
}


/* ======================================================
   INITIAL DELIVERY VALUES
   ====================================================== */

function initialize_delivery_values(frm, cdt, cdn) {

    const row = locals[cdt][cdn];

    const net_weight =
        flt(row.net_weight);

    const gross_weight =
        flt(row.gross_weight);

    if (net_weight <= 0) {
        return;
    }


    if (!flt(row.worker_metal_weight)) {

        frappe.model.set_value(
            cdt,
            cdn,
            "worker_metal_weight",
            flt(net_weight, 3)
        );
    }


    if (!flt(row.delivered_net_weight)) {

        frappe.model.set_value(
            cdt,
            cdn,
            "delivered_net_weight",
            flt(net_weight, 3)
        );
    }


    if (
        !flt(row.delivered_gross_weight) &&
        gross_weight > 0
    ) {

        frappe.model.set_value(
            cdt,
            cdn,
            "delivered_gross_weight",
            flt(gross_weight, 3)
        );
    }


    if (
        row.delivered_stone_weight === undefined ||
        row.delivered_stone_weight === null
    ) {

        const stone_weight =
            gross_weight -
            net_weight;


        frappe.model.set_value(
            cdt,
            cdn,
            "delivered_stone_weight",
            stone_weight > 0
                ? flt(stone_weight, 3)
                : 0
        );
    }
}


/* ======================================================
   WORKER FOLLOWS NET WEIGHT
   ====================================================== */

function sync_worker_from_net(frm, cdt, cdn) {

    const row = locals[cdt][cdn];

    const net_weight =
        flt(row.net_weight);

    if (net_weight <= 0) {
        return;
    }


    if (!flt(row.worker_metal_weight)) {

        frappe.model.set_value(
            cdt,
            cdn,
            "worker_metal_weight",
            flt(net_weight, 3)
        );
    }
}


/* ======================================================
   CUSTOMER RATE
   ====================================================== */

function fetch_customer_rate(frm, cdt, cdn) {

    const row = locals[cdt][cdn];

    if (
        !row.material ||
        !row.purity
    ) {
        return;
    }


    frappe.db.get_list(
        "Metal Rate",
        {
            filters: {
                metal: row.material,
                purity: row.purity,
                active: 1
            },

            fields: [
                "rate_per_gram",
                "rate_date"
            ],

            order_by:
                "rate_date desc",

            limit: 1
        }
    ).then(function(records) {

        if (
            records &&
            records.length
        ) {

            frappe.model.set_value(
                cdt,
                cdn,
                "rate_per_gram",
                flt(
                    records[0]
                        .rate_per_gram
                )
            );


            calculate_customer_side(
                frm,
                cdt,
                cdn
            );
        }
    });
}


/* ======================================================
   CUSTOMER CALCULATION
   ====================================================== */

function calculate_customer_side(frm, cdt, cdn) {

    const row = locals[cdt][cdn];

    let net_weight =
        flt(row.net_weight);


    if (
        net_weight <= 0 &&
        flt(row.gross_weight) > 0
    ) {

        net_weight =
            flt(row.gross_weight);


        frappe.model.set_value(
            cdt,
            cdn,
            "net_weight",
            flt(net_weight, 3)
        );
    }


    const wastage =
        flt(row.wastage_percentage);

    const rate =
        flt(row.rate_per_gram);

    const making =
        flt(row.making_charges);

    const hallmark =
        flt(row.hallmark_charges);

    const other =
        flt(row.other_charges);


    const equivalent_weight =
        net_weight *
        (100 + wastage) /
        100;


    const metal_value =
        equivalent_weight *
        rate;


    const quoted_amount =
        metal_value +
        making +
        hallmark +
        other;


    frappe.model.set_value(
        cdt,
        cdn,
        "equivalent_weight",
        flt(equivalent_weight, 3)
    );


    frappe.model.set_value(
        cdt,
        cdn,
        "quoted_amount",
        Math.ceil(quoted_amount)
    );


    frappe.model.set_value(
        cdt,
        cdn,
        "total_amount",
        Math.ceil(quoted_amount)
    );


    calculate_order_totals(frm);
}


/* ======================================================
   WORKER CALCULATION
   ====================================================== */

function calculate_worker_side(frm, cdt, cdn) {

    const row = locals[cdt][cdn];

    const metal_weight =
        flt(row.worker_metal_weight);

    const purity =
        flt(row.worker_purity_percentage) || 92;


    const pure_weight =
        metal_weight *
        purity /
        100;


    const wastage_percentage =
        flt(
            row.worker_wastage_percentage
        );


    const wastage_weight =
        flt(
            row.worker_wastage_weight
        );


    let equivalent_weight = 0;


    if (
        wastage_percentage > 0
    ) {

        equivalent_weight =
            metal_weight *
            (purity +
                wastage_percentage) /
            100;

    } else if (
        wastage_weight > 0
    ) {

        equivalent_weight =
            pure_weight +
            wastage_weight;

    } else {

        equivalent_weight =
            pure_weight;
    }


    const biscuit_rate =
        flt(
            row.worker_biscuit_rate
        );


    const metal_value =
        equivalent_weight *
        biscuit_rate;


    const hallmark =
        flt(
            row.worker_hallmark_charges
        );

    const document =
        flt(
            row.worker_document_charges
        );

    const travel =
        flt(
            row.worker_travel_charges
        );

    const other =
        flt(
            row.worker_other_charges
        );


    const total_worker_cost =
        metal_value +
        hallmark +
        document +
        travel +
        other;


    frappe.model.set_value(
        cdt,
        cdn,
        "worker_pure_weight",
        flt(
            pure_weight,
            3
        )
    );


    frappe.model.set_value(
        cdt,
        cdn,
        "worker_equivalent_weight",
        flt(
            equivalent_weight,
            3
        )
    );


    frappe.model.set_value(
        cdt,
        cdn,
        "worker_metal_value",
        Math.ceil(
            metal_value
        )
    );


    frappe.model.set_value(
        cdt,
        cdn,
        "worker_total_cost",
        Math.ceil(
            total_worker_cost
        )
    );


    update_order_worker_total(
        frm
    );
}


/* ======================================================
   DELIVERED NET WEIGHT CHANGED
   ====================================================== */

function update_delivery_from_net(frm, cdt, cdn) {

    const row = locals[cdt][cdn];

    const delivered_net =
        flt(
            row.delivered_net_weight
        );


    if (delivered_net < 0) {

        frappe.model.set_value(
            cdt,
            cdn,
            "delivered_net_weight",
            0
        );

        return;
    }


    const original_net =
        flt(row.net_weight);


    const adjustment =
        delivered_net -
        original_net;


    frappe.model.set_value(
        cdt,
        cdn,
        "delivery_weight_adjustment",
        flt(adjustment, 3)
    );


    const stone_weight =
        flt(
            row.delivered_stone_weight
        );


    const gross =
        delivered_net +
        stone_weight;


    frappe.model.set_value(
        cdt,
        cdn,
        "delivered_gross_weight",
        flt(gross, 3)
    );


    frappe.model.set_value(
        cdt,
        cdn,
        "worker_metal_weight",
        flt(delivered_net, 3)
    );


    calculate_worker_side(
        frm,
        cdt,
        cdn
    );


    calculate_delivery_amount(
        frm,
        cdt,
        cdn
    );
}


/* ======================================================
   DELIVERED GROSS WEIGHT CHANGED
   ====================================================== */

function update_stone_weight_from_gross(
    frm,
    cdt,
    cdn
) {

    const row = locals[cdt][cdn];

    const gross =
        flt(
            row.delivered_gross_weight
        );

    const net =
        flt(
            row.delivered_net_weight
        );


    if (gross < 0) {
        return;
    }


    let stone_weight =
        gross - net;


    if (stone_weight < 0) {
        stone_weight = 0;
    }


    frappe.model.set_value(
        cdt,
        cdn,
        "delivered_stone_weight",
        flt(stone_weight, 3)
    );


    const original_net =
        flt(row.net_weight);


    const adjustment =
        net - original_net;


    frappe.model.set_value(
        cdt,
        cdn,
        "delivery_weight_adjustment",
        flt(adjustment, 3)
    );


    frappe.model.set_value(
        cdt,
        cdn,
        "worker_metal_weight",
        flt(net, 3)
    );


    calculate_worker_side(
        frm,
        cdt,
        cdn
    );


    calculate_delivery_amount(
        frm,
        cdt,
        cdn
    );
}


/* ======================================================
   STONE WEIGHT CHANGED
   ====================================================== */

function update_gross_from_stone(
    frm,
    cdt,
    cdn
) {

    const row = locals[cdt][cdn];

    const net =
        flt(
            row.delivered_net_weight
        );


    let stone =
        flt(
            row.delivered_stone_weight
        );


    if (stone < 0) {

        stone = 0;

        frappe.model.set_value(
            cdt,
            cdn,
            "delivered_stone_weight",
            0
        );
    }


    const gross =
        net + stone;


    frappe.model.set_value(
        cdt,
        cdn,
        "delivered_gross_weight",
        flt(gross, 3)
    );


    calculate_delivery_amount(
        frm,
        cdt,
        cdn
    );
}


/* ======================================================
   DELIVERY WEIGHT ADJUSTMENT
   ====================================================== */

function apply_delivery_weight_adjustment(
    frm,
    cdt,
    cdn
) {

    const row = locals[cdt][cdn];

    const original_net =
        flt(row.net_weight);


    const adjustment =
        flt(
            row.delivery_weight_adjustment
        );


    let delivered_net =
        original_net +
        adjustment;


    if (delivered_net < 0) {
        delivered_net = 0;
    }


    frappe.model.set_value(
        cdt,
        cdn,
        "delivered_net_weight",
        flt(delivered_net, 3)
    );


    const stone =
        flt(
            row.delivered_stone_weight
        );


    const delivered_gross =
        delivered_net +
        stone;


    frappe.model.set_value(
        cdt,
        cdn,
        "delivered_gross_weight",
        flt(
            delivered_gross,
            3
        )
    );


    frappe.model.set_value(
        cdt,
        cdn,
        "worker_metal_weight",
        flt(delivered_net, 3)
    );


    calculate_worker_side(
        frm,
        cdt,
        cdn
    );


    calculate_delivery_amount(
        frm,
        cdt,
        cdn
    );
}


/* ======================================================
   DELIVERY AMOUNT
   ====================================================== */

function calculate_delivery_amount(
    frm,
    cdt,
    cdn
) {

    const row = locals[cdt][cdn];

    let final_amount =
        flt(row.total_amount) +
        flt(
            row.delivery_amount_adjustment
        );


    if (final_amount < 0) {
        final_amount = 0;
    }


    frappe.model.set_value(
        cdt,
        cdn,
        "final_amount",
        Math.ceil(final_amount)
    );


    calculate_order_totals(frm);
}


/* ======================================================
   PAYMENT VALIDATION
   ====================================================== */

function validate_payment_amount(
    frm,
    cdt,
    cdn
) {

    const row = locals[cdt][cdn];

    let other_paid = 0;


    (frm.doc.payments || [])
        .forEach(function(payment) {

            if (
                payment.name !==
                row.name
            ) {

                other_paid +=
                    flt(payment.amount);
            }

        });


    const grand_total =
        flt(frm.doc.grand_total);


    let remaining =
        grand_total -
        other_paid;


    if (remaining < 0) {
        remaining = 0;
    }


    if (
        flt(row.amount) >
        remaining
    ) {

        frappe.msgprint({

            title:
                "Payment Exceeds Balance",

            message:
                "Payment cannot be greater than the remaining balance of " +
                format_currency(
                    remaining
                ),

            indicator:
                "red"
        });


        frappe.model.set_value(
            cdt,
            cdn,
            "amount",
            0
        );
    }


    calculate_order_totals(frm);
}


/* ======================================================
   ORDER TOTALS
   ====================================================== */

function calculate_order_totals(frm) {

    let subtotal = 0;


    (frm.doc.jewellery_items || [])
        .forEach(function(row) {

            let item_total =
                flt(row.total_amount) +
                flt(
                    row.delivery_amount_adjustment
                );


            if (item_total < 0) {
                item_total = 0;
            }


            subtotal +=
                item_total;
        });


    subtotal =
        Math.ceil(subtotal);


    const discount =
        Math.ceil(
            flt(frm.doc.discount)
        );


    let grand_total =
        subtotal -
        discount;


    if (grand_total < 0) {
        grand_total = 0;
    }


    let total_paid = 0;


    (frm.doc.payments || [])
        .forEach(function(payment) {

            total_paid +=
                flt(payment.amount);

        });


    total_paid =
        Math.ceil(total_paid);


    let balance =
        grand_total -
        total_paid;


    if (balance < 0) {
        balance = 0;
    }


    balance =
        Math.ceil(balance);


    frm.set_value(
        "subtotal",
        subtotal
    );


    frm.set_value(
        "grand_total",
        grand_total
    );


    frm.set_value(
        "advance_amount",
        total_paid
    );


    frm.set_value(
        "balance_amount",
        balance
    );
}


/* ======================================================
   SECTION VISIBILITY
   ====================================================== */

function update_section_visibility(frm) {

    const status =
        frm.doc.order_status || "";


    const worker_visible =
        [
            "Ordered to Worker",
            "Worker Finished",
            "Received",
            "Delivered"
        ].includes(status);


    const delivery_visible =
        [
            "Received",
            "Delivered"
        ].includes(status);


    const adjustment_visible =
        [
            "Delivered"
        ].includes(status);


    frm.set_df_property(
        "worker_production_section",
        "hidden",
        !worker_visible
    );


    frm.set_df_property(
        "actual_delivery_section",
        "hidden",
        !delivery_visible
    );


    frm.set_df_property(
        "delivery_adjustment_section",
        "hidden",
        !adjustment_visible
    );
}

frappe.ui.form.on("Jewellery Order", {

    refresh: function(frm) {
        control_submit_button(frm);
    },

    order_status: function(frm) {
        control_submit_button(frm);
    },

    validate: function(frm) {

        if (
            frm.doc.docstatus === 0 &&
            frm._action === "Submit" &&
            frm.doc.order_status !== "Delivered"
        ) {

            frappe.msgprint({
                title: "Order Not Ready",
                message:
                    "Jewellery Order can be submitted only when Order Status is Delivered.",
                indicator: "orange"
            });

            frappe.validated = false;
        }
    }
});


function control_submit_button(frm) {

    if (frm.doc.docstatus !== 0) {
        return;
    }

    const can_submit =
        frm.doc.order_status === "Delivered";


    if (frm.page && frm.page.btn_primary) {

        if (can_submit) {

            frm.page.btn_primary
                .removeAttr("disabled");

        } else {

            frm.page.btn_primary
                .attr("disabled", "disabled");

        }
    }
}

frappe.ui.form.on("Jewellery Order", {

    refresh: function(frm) {
        add_retail_stock_button(frm);
    },

    order_status: function(frm) {
        add_retail_stock_button(frm);
    }
});


function add_retail_stock_button(frm) {

    if (!frm.page) {
        return;
    }

    frm.remove_custom_button(
        "Send to Retail Stock"
    );

    if (
        frm.is_new() ||
        frm.doc.docstatus !== 0 ||
        frm.doc.order_status !== "Received"
    ) {
        return;
    }

    frm.add_custom_button(
        "Send to Retail Stock",
        function() {
            open_retail_stock_dialog(frm);
        }
    );
}


function open_retail_stock_dialog(frm) {

    frappe.call({
        method:
            "jewellery_management.jewellery_management.stock_hooks.get_order_stock_candidates",

        args: {
            order_name: frm.doc.name
        },

        freeze: true,

        freeze_message:
            "Checking Retail Stock Items..."

    }).then(function(response) {

        const rows =
            response.message || [];

        if (!rows.length) {

            frappe.msgprint({
                title: "No Items",
                message:
                    "This Jewellery Order has no items.",
                indicator: "orange"
            });

            return;
        }


        show_transfer_dialog(
            frm,
            rows
        );

    });
}


function show_transfer_dialog(
    frm,
    rows
) {

    const fields = [];

    let missing_items = [];


    rows.forEach(function(row) {

        fields.push({
            fieldtype: "Section Break",
            label:
                "Item " +
                row.idx +
                " — " +
                row.item_name +
                " — " +
                row.delivered_net_weight.toFixed(3) +
                " g"
        });


        if (row.already_transferred) {

            fields.push({

                fieldtype: "HTML",

                fieldname:
                    "already_" +
                    row.idx,

                options:
                    "<div style='padding:8px 0'>" +
                    "<b>Already transferred to Retail Stock</b>" +
                    "</div>"
            });

            return;
        }


        if (
            row.candidates &&
            row.candidates.length
        ) {

            const options =
                row.candidates.map(
                    function(candidate) {

                        return {
                            label:
                                candidate.stock_item_name +
                                " [" +
                                candidate.stock_identity_code +
                                "]",

                            value:
                                candidate.name
                        };

                    }
                );


            const option_text =
                options.map(
                    function(item) {

                        return (
                            item.value +
                            " : " +
                            item.label
                        );

                    }
                ).join("\n");


            fields.push({

                fieldtype: "Select",

                fieldname:
                    "stock_" +
                    row.idx,

                label:
                    "Retail Stock Item",

                options:
                    option_text,

                default:
                    options.length === 1
                        ? options[0].value
                        : "",

                reqd: 1
            });

        } else {

            missing_items.push(row);


            fields.push({

                fieldtype: "HTML",

                fieldname:
                    "missing_" +
                    row.idx,

                options:
                    "<div style='padding:8px 0'>" +
                    "<div style='margin-bottom:6px'>" +
                    "<b>No Retail Stock Item found.</b>" +
                    "</div>" +
                    "<button type='button' " +
                    "class='btn btn-sm btn-secondary " +
                    "create-retail-stock-item' " +
                    "data-idx='" +
                    row.idx +
                    "'>" +
                    "Create Retail Stock Item" +
                    "</button>" +
                    "</div>"
            });
        }

    });


    fields.push({

        fieldtype: "HTML",

        fieldname: "weight_info",

        options:
            "<div style='margin-top:8px'>" +
            "<b>Stock Weight:</b> Delivered Net Weight" +
            "</div>"
    });


    const dialog =
        new frappe.ui.Dialog({

            title:
                "Send to Retail Stock",

            fields:
                fields,

            primary_action_label:
                "Transfer Selected Items",

            primary_action:
                function(values) {

                    const selections = [];

                    let missing_selection =
                        false;


                    rows.forEach(
                        function(row) {

                            if (
                                row.already_transferred
                            ) {
                                return;
                            }


                            /*
                             * Items without an existing
                             * Retail Stock Item must first
                             * be created.
                             */

                            if (
                                !row.candidates ||
                                !row.candidates.length
                            ) {

                                missing_selection =
                                    true;

                                return;
                            }


                            const value =
                                values[
                                    "stock_" +
                                    row.idx
                                ];


                            if (!value) {

                                missing_selection =
                                    true;

                                return;
                            }


                            const stock_name =
                                value.includes(
                                    " : "
                                )
                                    ? value.split(
                                        " : "
                                    )[0]
                                    : value;


                            selections.push({

                                row_name:
                                    row.row_name,

                                retail_stock_item:
                                    stock_name
                            });

                        }
                    );


                    if (missing_selection) {

                        frappe.msgprint({

                            title:
                                "Complete Retail Stock Selection",

                            message:
                                "Create or select a Retail Stock Item for every item before transferring.",

                            indicator:
                                "orange"
                        });

                        return;
                    }


                    if (!selections.length) {

                        frappe.msgprint({

                            title:
                                "Nothing to Transfer",

                            message:
                                "There are no new items to transfer.",

                            indicator:
                                "orange"
                        });

                        return;
                    }


                    frappe.call({

                        method:
                            "jewellery_management.jewellery_management.stock_hooks.send_items_to_retail_stock",

                        args: {

                            order_name:
                                frm.doc.name,

                            selections:
                                JSON.stringify(
                                    selections
                                )
                        },

                        freeze:
                            true,

                        freeze_message:
                            "Sending items to Retail Stock..."

                    }).then(
                        function() {

                            dialog.hide();

                            frm.reload_doc();

                            frappe.show_alert({

                                message:
                                    "Items sent to Retail Stock successfully.",

                                indicator:
                                    "green"
                            });

                        }
                    );

                }

        });


    dialog.show();


    /*
     * Create Retail Stock Item button.
     */

    dialog.$wrapper.on(
        "click",
        ".create-retail-stock-item",
        function() {

            const idx =
                Number(
                    this.dataset.idx
                );


            const row =
                rows.find(
                    function(item) {
                        return item.idx === idx;
                    }
                );


            if (!row) {
                return;
            }


            create_new_stock_item(
                frm,
                row,
                dialog
            );

        }
    );
}


function create_new_stock_item(
    frm,
    row,
    parent_dialog
) {

    const dialog =
        new frappe.ui.Dialog({

            title:
                "Create Retail Stock Item",

            fields: [

                {
                    fieldtype:
                        "Data",

                    fieldname:
                        "stock_item_name",

                    label:
                        "Stock Item Name",

                    reqd:
                        1,

                    default:
                        row.item_name
                },

                {
                    fieldtype:
                        "Link",

                    fieldname:
                        "article_category",

                    label:
                        "Article Category",

                    options:
                        "Jewellery Item Type",

                    reqd:
                        1,

                    default:
                        row.item_name
                },

                {
                    fieldtype:
                        "Select",

                    fieldname:
                        "metal",

                    label:
                        "Metal",

                    options:
                        "Gold\nSilver",

                    reqd:
                        1,

                    default:
                        row.material || ""
                },

                {
                    fieldtype:
                        "Link",

                    fieldname:
                        "purity",

                    label:
                        "Purity",

                    options:
                        "Metal Purity",

                    default:
                        row.purity || ""
                },

                {
                    fieldtype:
                        "Data",

                    fieldname:
                        "stock_identity_code",

                    label:
                        "Stock Identity Code",

                    reqd:
                        1
                }

            ],

            primary_action_label:
                "Create",

            primary_action:
                function(values) {

                    frappe.call({

                        method:
                            "jewellery_management.jewellery_management.stock_hooks.create_retail_stock_item",

                        args: {

                            stock_item_name:
                                values.stock_item_name,

                            article_category:
                                values.article_category,

                            metal:
                                values.metal,

                            purity:
                                values.purity,

                            stock_identity_code:
                                values.stock_identity_code
                        },

                        freeze:
                            true,

                        freeze_message:
                            "Creating Retail Stock Item..."

                    }).then(
                        function(response) {

                            const created =
                                response.message;


                            dialog.hide();

                            /*
                             * Close the old dialog and
                             * reopen it so the new item
                             * appears as a selectable option.
                             */

                            parent_dialog.hide();

                            frappe.show_alert({

                                message:
                                    "Retail Stock Item created.",

                                indicator:
                                    "green"
                            });


                            frappe.after_ajax(
                                function() {

                                    open_retail_stock_dialog(
                                        frm
                                    );

                                }
                            );

                        }
                    );

                }
        });


    dialog.show();
}
